import OpenAI from 'openai';

export interface RetryOptions {
  maxAttempts: number;
  baseDelayMs: number;
  sleep: (ms: number) => Promise<void>;
  random: () => number;
}

export const DEFAULT_RETRY_OPTIONS: RetryOptions = {
  maxAttempts: 3,
  baseDelayMs: 500,
  sleep: (ms) => new Promise((resolve) => setTimeout(resolve, ms)),
  random: Math.random,
};

const JITTER_FRACTION = 0.1;

const TRANSIENT_CODES = new Set([
  'ECONNRESET',
  'ECONNREFUSED',
  'ECONNABORTED',
  'ETIMEDOUT',
  'EHOSTUNREACH',
  'ENETUNREACH',
  'ENETDOWN',
  'EPIPE',
  'EAI_AGAIN',
  'UND_ERR_CONNECT_TIMEOUT',
  'UND_ERR_HEADERS_TIMEOUT',
  'UND_ERR_BODY_TIMEOUT',
  'UND_ERR_SOCKET',
]);

// Transient failures only: SDK connection/timeout errors, HTTP 429, and
// HTTP 5xx (plus raw socket codes found on an error's cause chain, for
// clients that surface fetch failures unwrapped). Other 4xx statuses and
// application errors like malformed responses are not retried.
export function isRetryableError(err: unknown): boolean {
  let current: unknown = err;
  for (let depth = 0; depth < 8 && current != null; depth++) {
    if (current instanceof OpenAI.APIConnectionError) return true;
    if (current instanceof OpenAI.APIError) {
      const status = current.status;
      return status === 429 || (typeof status === 'number' && status >= 500);
    }
    const code = (current as { code?: unknown }).code;
    if (typeof code === 'string' && TRANSIENT_CODES.has(code)) return true;
    current = (current as { cause?: unknown }).cause;
  }
  return false;
}

function attemptDelayMs(attempt: number, opts: RetryOptions): number {
  const backoff = opts.baseDelayMs * 2 ** (attempt - 1);
  const jitter = backoff * JITTER_FRACTION * (opts.random() * 2 - 1);
  return Math.max(0, backoff + jitter);
}

export async function withRetry<T>(
  fn: () => Promise<T>,
  options?: Partial<RetryOptions>,
): Promise<T> {
  const opts: RetryOptions = { ...DEFAULT_RETRY_OPTIONS, ...options };
  let lastError: unknown;
  for (let attempt = 1; attempt <= opts.maxAttempts; attempt++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;
      if (attempt === opts.maxAttempts || !isRetryableError(err)) {
        throw err;
      }
      await opts.sleep(attemptDelayMs(attempt, opts));
    }
  }
  throw lastError;
}

