import OpenAI from 'openai';
import { describe, expect, it } from 'vitest';
import { isRetryableError, withRetry } from './retry.js';
import { TranslationError } from './translator.js';

const apiError = (status: number) =>
  OpenAI.APIError.generate(status, undefined, `status ${status}`, new Headers());

const noSleep = () => Promise.resolve();

describe('isRetryableError', () => {
  it('treats connection errors as retryable', () => {
    const err = new OpenAI.APIConnectionError({
      message: 'connection error',
      cause: new Error('socket hangup'),
    });
    expect(isRetryableError(err)).toBe(true);
  });

  it('treats connection timeouts as retryable', () => {
    expect(isRetryableError(new OpenAI.APIConnectionTimeoutError({}))).toBe(
      true,
    );
  });

  it.each([500, 502, 503, 599])('treats HTTP %i as retryable', (status) => {
    expect(isRetryableError(apiError(status))).toBe(true);
  });

  it('treats HTTP 429 as retryable', () => {
    expect(isRetryableError(apiError(429))).toBe(true);
  });

  it.each([400, 401, 403, 404, 422])(
    'treats HTTP %i as non-retryable',
    (status) => {
      expect(isRetryableError(apiError(status))).toBe(false);
    },
  );

  it('treats generic application errors as non-retryable', () => {
    expect(isRetryableError(new Error('boom'))).toBe(false);
    expect(isRetryableError(new TranslationError('empty translation response')))
      .toBe(false);
  });

  it('treats raw socket error codes on the cause chain as retryable', () => {
    const socket = Object.assign(new Error('reset'), { code: 'ECONNRESET' });
    const wrapped = new TypeError('fetch failed', { cause: socket });
    expect(isRetryableError(wrapped)).toBe(true);
  });
});

describe('withRetry', () => {
  it('returns the result on first success without sleeping', async () => {
    const delays: number[] = [];
    const out = await withRetry(async () => 'ok', {
      sleep: async (ms) => {
        delays.push(ms);
      },
    });
    expect(out).toBe('ok');
    expect(delays).toEqual([]);
  });

  it('backs off exponentially between attempts', async () => {
    const delays: number[] = [];
    let calls = 0;
    await expect(
      withRetry(
        async () => {
          calls++;
          throw apiError(503);
        },
        {
          sleep: async (ms) => {
            delays.push(ms);
          },
          random: () => 0.5,
        },
      ),
    ).rejects.toThrow();
    expect(calls).toBe(3);
    expect(delays).toEqual([500, 1000]);
  });

  it('applies jitter within the configured fraction', async () => {
    const delays: number[] = [];
    let calls = 0;
    await expect(
      withRetry(
        async () => {
          calls++;
          throw apiError(500);
        },
        {
          sleep: async (ms) => {
            delays.push(ms);
          },
          random: () => 1,
        },
      ),
    ).rejects.toThrow();
    expect(calls).toBe(3);
    expect(delays[0]).toBeCloseTo(550);
    expect(delays[1]).toBeCloseTo(1100);
  });

  it('does not retry non-retryable errors', async () => {
    let calls = 0;
    await expect(
      withRetry(
        async () => {
          calls++;
          throw apiError(400);
        },
        { sleep: noSleep },
      ),
    ).rejects.toThrow();
    expect(calls).toBe(1);
  });

  it('surfaces the last error after attempts are exhausted', async () => {
    const last = apiError(500);
    await expect(
      withRetry(
        async () => {
          throw last;
        },
        { sleep: noSleep },
      ),
    ).rejects.toBe(last);
  });
});

