describe('OpenAICompatTranslator retries', () => {
  const segment = { text: 'How are you?', speaker: 'Speaker 1' };
  const noDelay = { sleep: async () => {}, random: () => 0.5 };
  const apiError = (status: number) =>
    OpenAI.APIError.generate(status, undefined, `status ${status}`, new Headers());

  function scriptedClient(script: ReadonlyArray<'ok' | Error>) {
    const calls: number[] = [];
    const factory = () =>
      ({
        chat: {
          completions: {
            create: async () => {
              const step = script[Math.min(calls.length, script.length - 1)]!;
              calls.push(calls.length);
              if (step !== 'ok') throw step;
              return { choices: [{ message: { content: 'translated' } }] };
            },
          },
        },
      }) as unknown as Pick<OpenAI, 'chat'>;
    return { calls, factory };
  }

  it('retries a transient 5xx failure and then succeeds', async () => {
    const { calls, factory } = scriptedClient([apiError(500), 'ok']);
    const t = new OpenAICompatTranslator(
      endpoint('https://p'),
      undefined,
      factory,
      noDelay,
    );
    const out = await t.translate(segment, [], 'vi');
    expect(out).toBe('translated');
    expect(calls).toHaveLength(2);
  });

  it('retries a rate-limit 429 failure', async () => {
    const { calls, factory } = scriptedClient([apiError(429), 'ok']);
    const t = new OpenAICompatTranslator(
      endpoint('https://p'),
      undefined,
      factory,
      noDelay,
    );
    const out = await t.translate(segment, [], 'vi');
    expect(out).toBe('translated');
    expect(calls).toHaveLength(2);
  });

  it('retries a network connection failure', async () => {
    const { calls, factory } = scriptedClient([
      new OpenAI.APIConnectionError({ message: 'connection error' }),
      'ok',
    ]);
    const t = new OpenAICompatTranslator(
      endpoint('https://p'),
      undefined,
      factory,
      noDelay,
    );
    const out = await t.translate(segment, [], 'vi');
    expect(out).toBe('translated');
    expect(calls).toHaveLength(2);
  });

  it('fails immediately on a non-retryable 4xx without retrying', async () => {
    const { calls, factory } = scriptedClient([
      apiError(400),
      apiError(400),
      apiError(400),
    ]);
    const t = new OpenAICompatTranslator(
      endpoint('https://p'),
      undefined,
      factory,
      noDelay,
    );
    await expect(t.translate(segment, [], 'vi')).rejects.toBeInstanceOf(
      TranslationError,
    );
    expect(calls).toHaveLength(1);
  });

  it('does not retry malformed (empty) responses', async () => {
    let calls = 0;
    const factory = () =>
      ({
        chat: {
          completions: {
            create: async () => {
              calls++;
              return { choices: [{ message: { content: '   ' } }] };
            },
          },
        },
      }) as unknown as Pick<OpenAI, 'chat'>;
    const t = new OpenAICompatTranslator(
      endpoint('https://p'),
      undefined,
      factory,
      noDelay,
    );
    await expect(t.translate(segment, [], 'vi')).rejects.toBeInstanceOf(
      TranslationError,
    );
    expect(calls).toBe(1);
  });

  it('gives up after 3 attempts and surfaces the failure', async () => {
    const { calls, factory } = scriptedClient([
      apiError(503),
      apiError(503),
      apiError(503),
    ]);
    const t = new OpenAICompatTranslator(
      endpoint('https://p'),
      undefined,
      factory,
      noDelay,
    );
    await expect(t.translate(segment, [], 'vi')).rejects.toBeInstanceOf(
      TranslationError,
    );
    expect(calls).toHaveLength(3);
  });
});

